(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,390282,n=>{"use strict";var s=n.i(843476),e=n.i(811337);function l(n){let l={em:"em",li:"li",p:"p",strong:"strong",ul:"ul",...(0,e.useMDXComponents)(),...n.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:h,AnketaPoint:d,AnketaProse:j,Whisper:x}=l;return r||i("AnketaCollapse",!0),c||i("AnketaGroup",!0),h||i("AnketaList",!0),d||i("AnketaPoint",!0),j||i("AnketaProse",!0),x||i("Whisper",!0),(0,s.jsxs)(c,{children:[(0,s.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,s.jsxs)(h,{children:[(0,s.jsxs)(d,{title:"Имя персонажа [русс|англ]",children:[(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"Салазар Фейнман | Salazar Feynman"})}),(0,s.jsxs)(l.ul,{children:["\n",(0,s.jsxs)(l.li,{children:["При жизни: ",(0,s.jsx)(l.strong,{children:"Доменико Лаццери"})," — имя, данное при рождении. Выступает своеобразным слабым местом феникса. Знакомы с ним лишь самые близкие союзники и друзья;"]}),"\n",(0,s.jsxs)(l.li,{children:["Псевдоним при жизни: ",(0,s.jsx)(l.strong,{children:"Франческо Салазар"}),";"]}),"\n",(0,s.jsx)(l.li,{children:"Уважительное обращение – мистер/господин Фейнман. При неформальном общении на равных, например при личном разговоре с Верховным Арбитром, допустимо использовать «Салазар» с обращением на «вы». Сокращения вроде «Сэл» могут использоваться в описаниях, но в разговоре между персонажами это прямое оскорбление."}),"\n"]})]}),(0,s.jsx)(d,{title:"Возраст",children:(0,s.jsxs)(l.ul,{children:["\n",(0,s.jsx)(l.li,{children:"прожитый на земле: 59 лет."}),"\n",(0,s.jsx)(l.li,{children:"дата рождения — 12.05.1399г. | смерти — 07.01.1459г."}),"\n",(0,s.jsx)(l.li,{children:"прожитый в Загробном мире как грешная душа: 559 лет."}),"\n"]})}),(0,s.jsx)(d,{title:"Пол",children:(0,s.jsx)(l.p,{children:"Мужской"})}),(0,s.jsxs)(d,{title:"Раса",children:[(0,s.jsx)(l.p,{children:"Фэнхуан (Чжугун)."}),(0,s.jsxs)(l.ul,{children:["\n",(0,s.jsx)(l.li,{children:"Как и многие представители расы китайских фениксов, Доменико при жизни был подвержен влиянию эмоций. Горячность характера боролась со стремлением к познанию мира путем созерцания и глубокого понимания чужеродной культуры. Противоположности, сходные с двойственностью Луны и Солнца, требующие поиска тонкого баланса. Стоит отметить, что по сравнению с сородичами Доменико более склонен к “метаниям” – эмоциональным вспышкам и, наоборот, периодам отчуждения, поглощенного эзотерическими размышлениями о нематериальном. Этот дефект перешел с ним в Энкраж и послужил одной из причин изгнания из Империи Лун;"}),"\n",(0,s.jsx)(l.li,{children:"Для Доменико, а в дальнейшем и Салазара, характерно стремление к самопознанию и философии, хоть эти изыскания и отравлены идеями о превосходстве собственной личности и трансгуманизме. Распространение “учения” стремится не к массовому охвату, а скорее к глубоко персональному подходу. Его принципы и цели, развиваясь со временем, не содержат лжи и подковерных интриг. Он обещает дорогу к божественному возвышению и сам без малейшей доли сомнений верит в свои слова. Контроль для него не цель, а лишь побочный эффект стремления познать мир и самого себя;"}),"\n",(0,s.jsx)(l.li,{children:"На протяжении всего мирского пути за Доменико следует безумие. Начиная жизнь подающим надежды студентом, заканчивает он её в пучине гротескных идей, гедонизма и полной убежденности в собственной божественной избранности."}),"\n"]})]})]})}),(0,s.jsxs)(r,{title:"Психологический профиль",children:[(0,s.jsx)(r,{title:"Характер",children:(0,s.jsxs)(j,{children:[(0,s.jsx)(l.p,{children:"Салазар по природе своей человек не простой. Он многое видел, многое пережил и вынес нередко начертанные кровью уроки, оставившие глубокие следы на его мировоззрении. Феникс высоко ценит все чего достиг и готов до последнего защищать свое наследие в этом мире. Он был сыном, он считал себя святым духом, теперь же он видит себя родительской фигурой в созданной его руками семье."}),(0,s.jsx)(l.p,{children:"Обычное состояние Салазара это одна сплошная театральная постановка. Так, в Академии он добрый и мудрый волшебник. В коридорах Телестериона загадочный служитель эонов греха. На собраниях Научной Ассоциации строгий Архивариус, а в Храме Предсказаний уважаемый религиозный деятель. Выступает он помпезно, ярко, с применением спецэффектов, играя словами и эмоциями зрителей."}),(0,s.jsx)(l.p,{children:"Этот маскарад можно назвать даже не столько защитной реакцией, сколько комфортной средой обитания, обустроенной фениксом для собственного развлечения, но и в целях весьма практичных. Такой стиль менеджмента уже стал для него настолько привычным, что не каждый старший грешник найдет края у маски."}),(0,s.jsx)(l.p,{children:"Феникс внимателен к собеседнику, общителен и терпелив. Он всегда найдет способ поддержать пребывающего в душевных метаниях персонажа (если тот по какой-то причине интересен мужчине). В цикл Луны слова его проникновенны и притягательны, в цикл Солнца полны амбиций и вдохновения. Фэнхуан способен найти общий язык с персонажем любого мировоззрения, но лишь не в ущерб себе. Благожелателен он исключительно к тем грешникам, которые не мешают ему в достижении поставленных целей. Ответ всегда будет соразмерен прегрешению."}),(0,s.jsx)(l.p,{children:"Конечно, мелкие склоки молодых грешников или волевые подвижки гордых одиночек волновать его сердце вряд ли будут. Все же, у Архивариуса есть дела поважнее, чем наказывать молодежь за мелкие проступки."}),(0,s.jsx)(l.p,{children:"Любимчики для Салазара всегда стоят на особом месте. Сердце его изрезано сотнями смертей дорогих друзей, любовников, подопечных, но как не парадоксально, тяга к привязанностям никуда не делась, лишь разрастаясь со временем. Он очень дорожит значимыми для него персонажами, словно это его собственные дети. Вопреки репутации бескомпромиссного лидера он не готов разменивать людей на материальное преимущество, хоть и тщательно это скрывает."}),(0,s.jsx)(l.p,{children:"Боль от потерь прошлого феникс давно принял как часть себя. Душевные терзания и безумие отхлынули словно волна. Рано или поздно они вернутся, с новой разрушительной силой, возможно положив конец существованию Салазара. Но сейчас он находится на островке спокойствия, с переменным успехом прикрывая старые раны."}),(0,s.jsx)(l.p,{children:"Это, конечно, совершенно не означает, что эмоции над фениксом не властны, совсем напротив. Он может как от всей души рассмеяться от хорошей шутки, так и всерьез рассердиться. Он способен тепло любить и горячо ненавидеть. Иногда это полезно для достижения его целей, иногда нет. Да, его контроль над собой весьма высок на фоне опыта и принадлежности к фэнхуанам, но даже сквозь маски Салазар зачастую умудряется быть честным в своих сиюминутных порывах."}),(0,s.jsx)(l.p,{children:"Тем не менее, когда шутки кончились и ситуация требует безотлагательных действий феникс ведет себя рассудительно и жестко. В такие моменты просыпается твердый как скала мужчина, не останавливающийся ни перед чем ради поставленной цели."}),(0,s.jsx)(l.p,{children:"Салазар не видит и не понимает деления на белое и черное. Охотник, пожираемый тигром, есть жертва несправедливости мира, или же справедливо караемый нарушитель спокойствия зверя? Фэнхуан смотрит на окружающую действительность в системе координат баланса и благоразумия. Он не станет делать что-то лишь потому, что деяние является “правильным” или “хорошим”, но и не будет терзать невинного ради удовлетворения жажды крови. Все происходящие в мире и социуме процессы действуют и сталкиваются в череде закономерностей, не подчиняющихся детским соображениям о героизме или злодеяниях. Смерть есть часть естественного хода дел. Ложь — опасный, но полезный инструмент."}),(0,s.jsx)(l.p,{children:"Для Салазара мир человеческих взаимоотношений — это танец на карнавале эмоций. Ему легко менять маски, раз за разом обманывая собеседника и самого себя. Когда толпа жаждет твердости духа и жесткого лидерства, он предстает непреодолимой силой. Когда грешник жаждет покаяния и прощения, феникс окружит его шелками и бархатом. Он будет тем, кем следует, пойдет на все, чтобы его устремления были воплощены в жизнь. Сгорит и воспрянет вновь, с новым обличьем, с новым лицом, пока то, что должно быть сделано, не воплотится в реальность."})]})}),(0,s.jsx)(r,{title:"Страхи",children:(0,s.jsxs)(h,{children:[(0,s.jsx)(d,{title:"Поддаться безумию фэнхуан",children:(0,s.jsx)(l.p,{children:"Салазар боролся с собой на протяжении всего своего существования в Энкраже. Иррациональность его поступков и намерений доставила немало боли самому мужчине и окружающим. Сейчас, когда феникс сумел совладать со своим естеством, он боится вновь утратить контроль, пока целостность его личности растворяется в череде перерождений."})}),(0,s.jsx)(d,{title:"Потеря власти и значимости",children:(0,s.jsx)(l.p,{children:"Всё окружающее феникса было построено его руками за долгие годы кропотливой работы. Все люди, что повинуются его слову, все ресурсы, реками текущие, словно кровь, наполняющие вены подконтрольных ему структур, всё это является частью его самого. И без всего этого, быть может, от него ничего и не останется вовсе."})}),(0,s.jsx)(d,{title:"Беспокойство за подведомственные организации",children:(0,s.jsx)(l.p,{children:"Членов подведомственных организаций Салазар действительно любит, считая их жемчужинами в его руках. Он по настоящему боится, что его подопечные могут пострадать или погибнуть. Конечно, фаворитизм феникса весьма избирателен."})}),(0,s.jsx)(d,{title:"Неосуществимость веры в божественное возвышение",children:(0,s.jsx)(l.p,{children:"Феникс свято верит, что грешник способен преодолеть оковы своей оболочки и возвыситься. Долгие века ушли у попечителя храма предсказаний на исследование этой гипотезы. Салазара ужасает сама мысль, что все эти труды могут оказаться напрасны."})}),(0,s.jsx)(d,{title:"Забвение",children:(0,s.jsx)(l.p,{children:"Страх умереть и быть забытым грешниками. Не оставить следа в мире. Феникс дорожит своими творениями и союзниками. Он всеми силами старается создать нечто в его глазах прекрасное и судьба кануть в небытие для него представляется невероятно трагичной."})}),(0,s.jsx)(d,{title:"Апейрофобия",children:(0,s.jsx)(l.p,{children:"Боязнь неизведанного. Персонажу внушает страх произошедшее с Братством Крови. Этот страх для него имеет в некотором роде лавкрафтовские мотивы. Факт того, что само знание может оказаться ужасающим чудовищем по ту сторону завесы, не дает Салазару покоя темными ночами."})})]})}),(0,s.jsx)(r,{title:"Мечты, цели",children:(0,s.jsxs)(j,{children:[(0,s.jsxs)(l.p,{children:[(0,s.jsx)(l.strong,{children:"Забота о связанных."})," Малая цель, которая, впрочем, довольно свежа и обладает ценностью для Салазара. Он действительно желает избавить удивительных в своей чужеродности людей верхнего мира от скверны греха. Хоть он и сам пока не определился, является то проявлением любви к ближнему или увлекательным научным проектом."]}),(0,s.jsxs)(l.p,{children:[(0,s.jsx)(l.strong,{children:"Трансгуманизм, стремление к божественному."})," Салазар и в том числе приближенные в Секторе Одиль исследуют тела грешников в попытках продвинуться в раскрытии их потенциала. Параллельно ведутся работы по созданию искусственных оболочек и усиления естественных. Казалось бы недостижимая, эта цель ведет за собой множество светлых умов."]}),(0,s.jsxs)(l.p,{children:[(0,s.jsx)(l.strong,{children:"Почувствовать себя родителем."})," Одна из причин, почему феникс окружает себя организациями и последователями – это его непреодолимое стремление обрести нечто родственное в этом темном мире. Он по-отечески относится к своим последователям и союзникам, а каждый собранный им автоматон подобен для него ребенку."]}),(0,s.jsxs)(l.p,{children:[(0,s.jsx)(l.strong,{children:"Создать разумный и мыслящий артефакт, способный сравняться с легендарными орудиями."})," Иными словами, цель любого артифекса. Являясь опытным инженером и конструктором, Салазар стремится достигнуть вершин этого мастерства. Ради достижения этой цели он, например, разыскивает древнюю алхимическую машину."]}),(0,s.jsxs)(l.p,{children:[(0,s.jsx)(l.strong,{children:"Понять природу Третьего Мира."})," Являясь представителем расы фэнхуан, Салазар тонко чувствует проявления Третьего Мира. Явления семени греха будоражат сознание, а невидимая завеса раззадоривает пытливый ум. По мнению феникса, по ту сторону грешников может ждать как великое откровение, так и великая сила."]}),(0,s.jsxs)(l.p,{children:[(0,s.jsx)(l.strong,{children:"Обрести любимого человека, осуществить слияние эхосов."})," Несмотря на огромное число партнеров и бесчисленное количество видов близости, испытанных Салазаром при жизни и в посмертии, у феникса никогда по настоящему не было второй половинки. В современности, когда личность мужчины претерпела изменения, он ощущает оковы одиночества, которые так и не разрушило тепло родной души."]})]})}),(0,s.jsx)(r,{title:"Биография (при жизни)",children:(0,s.jsxs)(j,{children:[(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1399–1414 (0–15 лет): Детство и образование во Флоренции"})}),(0,s.jsx)(l.p,{children:"Доменико родился во Флоренции в семье зажиточного купца. Являясь плодом внебрачной связи, стоившей матери жизни, мальчишка в кругу семьи зачастую чувствовал себя белой вороной. В отличие от своих братьев, он не унаследовал типичные черты рода – его волосы были светлыми, глаза голубыми, а сам он выделялся высоким ростом, статной фигурой, громким голосом и приятными чертами лица. Впрочем, несмотря на все, семья принимала Доменико с теплотой. Мачеха терпимо относилась к неродному сыну, однако настояла, чтобы тот по достижению совершеннолетия был отдан в монастырь. Поэтому в воспитании юноши особое место занимала философия, а также основы богословия, которые должны были подготовить его к церковной карьере. Впрочем, у самого Доменико прослеживался врожденный интерес, даже в неком роде талант, к точным наукам. Переводы трудов Платона и Аристотеля зародили в нем стремление познавать мир в том числе и со строгой материалистической позиции, помимо навязываемой ему духовной."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1414–1419 (15–20 лет): Посвящение в монашеский орден"})}),(0,s.jsx)(l.p,{children:"По достижении пятнадцатилетнего возраста, следуя воле мачехи, Доменико вступил в орден доминиканцев. Этот шаг должен был обеспечить ему духовный путь и уберечь от возможного позора из-за его происхождения. Орден доминиканцев славился своей интеллектуальной традицией, стремлением к истине и борьбой с ересями. Доменико погрузился в изучение христианской теологии, осваивая труды Отцов Церкви и схоластиков. Особое влияние на него оказали сочинения Августина Блаженного и Фомы Аквинского, чьи идеи помогали ему осмыслить взаимосвязь разума и веры. Однако строгая монашеская дисциплина не всегда давалась ему легко. Случаем, чуть было не послужившим поводом для отлучения от церкви, стала поимка Доменико в келье соседнего монастыря. В постели с одной из юной доминиканок. Юноша сделал выводы из курьезного случая и с тех пор больше не попадался."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1419–1424 (20–25 лет): Учёба в Саламанкском университете (Испания)"})}),(0,s.jsx)(l.p,{children:"По настоянию ордена Доменико отправился в Саламанкский университет, один из крупнейших центров средневекового богословия и науки. Здесь он изучал схоластику, теологию, право и философию, а также знакомился с трудами арабских мыслителей, таких, как Авиценна и Аль-Фараби. Под влиянием их идей он начал задаваться вопросами о природе человека, соотношении божественного предопределения и свободы воли, границах церковного авторитета. Его бурный характер давал о себе знать и в академической среде – Доменико с азартом вступал в диспуты, порой проявляя чрезмерную резкость и нетерпимость к оппонентам."}),(0,s.jsx)(l.p,{children:"«Глупцы! Потомки вкусившего плод познания, увидеть истину не способны. Внемлите! Рафаил — רָפָאֵל — есть 30+1+80+200 = 311! Мужчина — אִישׁ — есть 300+10+1 = 311! Женщина — האשה — есть 5+300+1+5 = 311! Триединство! Единение! Бог родился человеком и умер на кресте!..»"}),(0,s.jsx)(l.p,{children:"Однако его острота ума и глубокие познания позволяли ему избегать порицания и даже приобретать авторитет среди преподавателей и студентов. Средства на обучение регулярно поступали от далекой, но безвозмездно любящей семьи, что обеспечивало ему свободу учёных изысканий. К концу обучения он всё больше склонялся к независимому мышлению, что закладывало основу его будущего внутреннего конфликта с официальной церковной позицией."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1424–1429 (25–30 лет): Возвращение во Флоренцию и кризис веры"})}),(0,s.jsx)(l.p,{children:"Завершив обучение, Доменико вернулся во Флоренцию, где занялся пастырским служением и богословской деятельностью. Однако его пребывание в городе оказалось недолгим. Его сомнения в догматах церкви усилились, а вместе с ними – ощущение, что он стоит выше окружающих. Со временем его проповеди становились всё более радикальными, а публичные выступления сопровождались вспышками гнева и экзальтации. Он бросал вызов богословам, вступал в яростные диспуты и не скрывал своего презрения к тем, кто, по его мнению, был неспособен узреть истину. Его мания величия и стремление к абсолютному знанию привели к конфликтам как с церковными властями, так и с родными. Не видя поддержки, чувствуя себя единственным гласом истины на всем белом свете, Доменико решил отправиться в странствие, движимый великой идеей – обойти весь мир в поисках высшей истины. Семья, видя нарастающее безумие сына и не желая скандалов, предпочла отпустить его восвояси."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1429–1434 (30–35 лет): Ближний Восток и Персия"})}),(0,s.jsx)(l.p,{children:"Флоренция → Венеция → Константинополь → Иерусалим → Сирия → Персия."}),(0,s.jsx)(l.p,{children:"Первые годы путешествия приносят Доменико океан впечатлений. Путешествуя под псевдонимом Франческо Салазар, он открывает новые, невиданные доселе просторы. От переживающей золотой век Венеции, через движущийся к закату Константинополь навстречу загадочному Иерусалиму, в надежде на добрую волю Францисканской Кустодии. Из первых уст он познает тонкости иудаизма, ислама, зороастризма. Посещает библиотеки, ведёт диспуты с богословами и мистиками, вступает в сложные и противоречивые отношения с религиозными фигурами разного рода и происхождения. Франческо видит в каждом учении отражение высшей истины, но его характер и экстравагантный образ жизни порой вызывают конфликты."}),(0,s.jsx)(l.p,{children:"Языковой барьер в первое время не становится непреодолимой проблемой, поскольку за время учебы в Саламанкском университете Доменико имел возможность изучить латынь и греческий. С ивритом он знакомится, изучая религиозные тексты. Частично касается арабского, благодаря трудам таких философов как Авиценна и Аль-Фараби, а затем развивает его в общении с мусульманскими народами. Препятствием для него станет персидский, но за годы путешествия по Средней Азии, благодаря общению с торговцами и мудрецами поддастся и он."}),(0,s.jsx)(l.p,{children:"Оставленная семьей скудная сумма денег быстро иссякает и Франческо приходится искать способы заработка. В посещаемых им городах он находит покровителей, зачастую через мимолетные любовные связи, предлагая в обмен интеллектуальные беседы, обещания приобщить жаждущих к самой сути мироздания и, конечно же, свое тело."}),(0,s.jsx)(l.p,{children:"Интересно, что к своим попечителям Франческо испытывает не только лишь скупой потребительский интерес. Отношениям этим он отдает всего себя, с головой погружаясь в вихрь эмоций и ощущений. В своем дневнике он пишет следующее:"}),(0,s.jsx)(l.p,{children:"«Воспоминания о времени, проведенном с тобой, раз за разом напоминают, как мне хотелось остаться навсегда в твоих теплых объятиях под светом солнца в нашем тихом уголке Яффы. Там, где шум порта растворяется в шепоте волн, а ветер с Великого моря приносит ароматы цитрусовых садов и свежевыловленной рыбы. Там, где твой смех, как шелк, сплетался с криками чаек, а взгляд, полный нежности, заставлял замирать луну и солнце на небесах...»"}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1434–1439 (35–40 лет): Средняя Азия (Бухара, Самарканд)"})}),(0,s.jsx)(l.p,{children:"Франческо следует по Шёлковому пути, переходя от каравана к каравану, изучая культуры и верования народов Средней Азии. В суфийских общинах он открывает для себя мистические практики, которые становятся для него откровением: зикр, экстатические танцы дервишей, медитации, приводящие к состоянию изменённого сознания. В учении суфиев он находит параллели с христианским мистицизмом, но, в отличие от католической догматики, суфизм предлагает непосредственное переживание божественного. Его размышления о природе Бога обогащаются идеей о внутреннем единении с Абсолютом через любовь и самопознание."}),(0,s.jsx)(l.p,{children:"Однако религиозные искания Франческо не ограничиваются только исламским мистицизмом. Встречи с шаманами кочевых народов заставляют его задуматься о роли духовных посредников между миром людей и высшими силами. Он участвует в ритуалах, наблюдает жертвоприношения и испытывает на себе воздействие местных трансовых практик. Эти опыты укрепляют его убеждение, что истина не заключена в одном единственном взгляде на мироздание, но разлита повсюду, в самых разных формах."}),(0,s.jsx)(l.p,{children:"В Средней Азии начинают формироваться первые доктрины его будущего учения. Медленно, но верно Франческо находит тех, кто готов слушать. Он аккуратно подбирает ключик к людям самых различных верований и идеологий, отталкиваясь от основ местных религий, плавно подводя к собственным измышлениям. Постепенно втираясь в доверие к пастве желающих внимать истине, он проповедует свои идеи о цикличности времени, о том, что Бог проявляется в разных формах, и что человеку необходимо искать божественное не только в догмах, но и себе самом. Его речи привлекают внимание – среди купцов, суфиев и путешественников появляются первые последователи. Двое из них становятся его постоянными спутниками, разделяя его странствия и поиски."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1439–1444 (40–45 лет): Индия (Дели, Варанаси)"})}),(0,s.jsx)(l.p,{children:"Переход через заснеженные перевалы Гиндукуша и суровые ущелья Гималаев стал для Франческо испытанием и мистическим очищением: голод, холод и немые взгляды каменных исполинов обнажили в нем жажду не столько выжить, сколько превзойти саму природу. В Индии, где воздух гудел от мантр и дыма погребальных костров Варанаси, его охватило чувство, будто все философские учения, все научные знания и эзотерические практики этого мира — лишь ступени к чему-то большему, что зреет в нем самом. Буддийские монахи, видя в нем отголоски бодхисаттвы, раскрывали тайны пустоты и нирваны; джайны-аскеты, чьи постные лица напоминали ему доминиканских затворников, учили непривязанности — но Франческо уже не довольствовался уроками. В его дневнике множились записи о том, что через спустя двести лет будет описано Василием Валентином как Ребис — алхимическое слияние мужского и женского, божественная андрогинность, что, как он верил, жила в нем с рождения."}),(0,s.jsx)(l.p,{children:"Он пишет, обращаясь к себе:\n«Ты – горнило, где свинец страха претворяется в золото воли. Ты – тот, кто несет в себе и Шиву, и Шакти, и Христа, и Марию…»"}),(0,s.jsx)(l.p,{children:"Открытая в ведических и буддийских текстах алхимия становится для него метафорой собственного преображения: в Дели он обменивает знания о греческой философии и арабской астрономии на рецепты расаяны, в храмах Варанаси толкует Упанишады, а ночами, при свете масляных ламп, чертит мандалы, где гематрические письмена — символ его избранности — сплетаются с янтрами. К нему прибиваются новые спутники: разочарованный раджпут, искавший истину в мече; вдова-танцовщица, чье тело помнило ритуалы девадаси; юный брахмачарья, пораженный речами о единстве Атмана и Брахмана. Их пятеро — столько, сколько элементов в тантрической традиции. Они спят на циновках в храмовых пристройках, питаются рисом, поданным милостыней, а Франческо, все чаще замолкая в середине проповеди, смотрит на свои руки, будто ждет, что сквозь кожу проступят золотые прожилки."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1444–1449 (45–50 лет): Тибет и Китай"})}),(0,s.jsx)(l.p,{children:"В ледяных монастырях Тибета, где ветер вырезал из тишины мантры “ॐ मणि पद्मे हूँ”, Франческо постигал ту грань, где дыхание становится молитвой, а медитация — побегом из плоти. Ламы, читавшие в его глазах отсвет Калачакры, допускали его к тайным мандалам, но он жаждал не секретов перерождений, а ключей к бессмертию. Спустившись с Гималаев в дымные долины Сычуани, он нашел то, что искал: даосские отшельники, чьи лица были изборождены временем, как кора древних кипарисов, учили его варить «пилюли бессмертия» в печах, высеченных в скалах, и вдыхать ци гор как эликсир вечности. В Шэньси, среди бамбуковых свитков с трактатами о инь и ян, его доктрина обрела плоть."}),(0,s.jsx)(l.p,{children:"«Человек — есть мост меж Озирисом и Исидой, где каждая кость — свиток Тота, а кровь подобна ртути. Сломай золотую клеть, как Шива сокрушает иллюзии в танце Натараджи. Взгляни — аколит Дао, пьет амриту из чаши Грааля, где четыре капли мудрости Вед сплетаются с гематрией «אָמֵן». Расплавь свинец костей в золото Калачакры, ибо Инь — это Лилит, целующая Ян-Христа в саду Гетсеманских огней. Ты — горнило, где Феникс Вавилона рождается из пепла Сансары, а шепот Лао-цзы сливается с воплями Диониса. Беги по мосту — или стань им, пока пульс Вселенной не превратил твоё сердце в колокол Вечности…»"}),(0,s.jsx)(l.p,{children:"Его «апостолы» — китаец-литератор, отвергший императорский двор; тибетская монахиня, сбежавшая из монастыря; персидский алхимик с руками, опаленными серой, — верили, что его дрожь во время медитаций есть знак преображения, а седина в волосах — не старость, но свет иного мира. Они строили обители в горах, собирали милостыню у крестьян, а ночами переписывали его «Гимны Единения», где Христос пил чашу с Лао-цзы, а Шива танцевал с Жёлтым Императором. Когда Франческо, облаченный в шелка, сотканные из пожертвований, взмывал в экстатическом танце, они видели, как сквозь его кожу мерцает золото бессмертной пилюли — или это блики факелов дрожали в слезах тех, кто поверил, что держит за руку бога."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"1449–1459 (50–60 лет): Жизнь в Китае в качестве лидера культа"})}),(0,s.jsx)(l.p,{children:"Десятилетие, когда секта цвела, как лотос в грязи придорожных канав, стало зеркалом самого Франческо: снаружи — позолота ритуалов, где тантрические мудры сплетались с даосскими «небесными союзами», внутри — гниение. В залах, украшенных шелками, пахло потом, опиумным дымом и медью — здесь, под цитаты из Камасутры, переложенные на латынь, “апостолы” превозносили соитие как алхимический акт, где семя должно было стать эликсиром. Но когда в 1457 году Франческо купил у малайских моряков экзотическую девчушку с кожей цвета тёмного мёда и глазами, как щели в маске Раху, баланс рухнул. Её тело, украшенное татуировками спиралей — может, картой неизвестных островов, может, знаком проклятия — стало чашей, из которой он пил яд, ещё не названный сифилисом. К 1469 году “живая икона” гнила заживо: кожа, усыпанная жемчужными шанкрами, напоминала пергамент с письменами чумы; пальцы, некогда чертившие мандалы, теперь отваливались, как глиняные осколки терракотовой армии. Последователи, однако, шептались, что это — последнее Великое Делание: плоть, очищающаяся огнём перед вознесением. Когда он умер, обняв распятие, сплетённое из бамбука и чёток Шивы, культ рассыпался, как прах от сожжённых “пилюль бессмертия”. Лишь в деревнях Сычуани старики показывали руины “Храма Единения”, где под обвалившейся крышей валялись пергаменты с гимнами, сожранные плесенью — будто сама земля переварила безумие, не оставив даже костей пророка."}),(0,s.jsx)(l.p,{children:"«Боль слабеет, а с нею и мой голос, но теперь за меня говорит моё сердце. Я жду, пока он взвешивает его на весах Времени. Врата позади, теперь я в верхних залах Обители. Слава очень близка здесь. Она сочится сквозь ткань Дома, распространяя свет. Мне удалось проскользнуть за спиной Дозорного; я знаю, как его тень лежит на Камне. Иногда я слышу, как Часы обсуждают друг с другом пути, по которым пойдёт мир. Я не буду жить. Я не умру. Быть может, однажды я поднимусь ещё выше.»"})]})}),(0,s.jsx)(r,{title:"Жизнь в Энкраже",children:(0,s.jsxs)(j,{children:[(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 1, Солнце 1459 - 1469"})}),(0,s.jsx)(l.p,{children:"Новую жизнь можно назвать не иначе как “приземлением”. Врата башни, для кого-то символ откровения высшего порядка, для Салазара оказываются дорогой к суровой реальности. Переродившийся и укомплектованный изящной металлической маской грешник поначалу приходит в восторг. Его мечта сбылась. Тело вновь на пике формы, не ведает мучений старости, а магический потенциал, словно жидкое золото, течет по его венам. Салазар наконец достиг цели стать богом. Он избранный!"}),(0,s.jsx)(l.p,{children:"Проблема в том, что в замке множество других таких же избранных и в какой-то мере Франческо вернулся к тому, с чего начинал. К его пылким речам никто не прислушивается. Люди посмеиваются и крутят пальцем у виска доводя солнечного феникса до белого каления. Достаточно скоро бывший мудрец, лидер и знаток человеческих сердец, находит новый путь к возвышению. Он развивает волшебную способность менять черты лица и объем тела, притворяясь другим человеком. Сэл (как его прозвали в те времена) принимается плести интриги, в попытках завоевать власть. Меняет лица как перчатки, подначивая врагов, сталкивая друзей. Все ради того, чтобы добиться своей цели - взойти на вершину."}),(0,s.jsx)(l.p,{children:"Конечно же юный фэнхуан, без существенного опыта, да еще и в цикле Солнца, не добивается успехов. Правда в том, что Салазар безумен. В своих поступках и реакциях окружающих он видит глобальный замысел и паутину коварства, но на деле его слова не несут смысла, а грешники смотрят на него с жалостью и отвращением. Одно радует. В тот период Сэлу с помощью магии удавалось успешно скрывать маску фэнхуана, что позволило избежать существенного репутационного удара в будущем."}),(0,s.jsx)(l.p,{children:"На протяжении года Салазар скитается по Энкражу. Его “интриги” чаще остаются незамеченными, но не раз переходя черту грешник оказывается в канаве, избитый и потеряв все нажитое имущество. Переломным моментом становится встреча с Реджинальдом де Моревилем. По его словам, рыцарь на службе Генриха II при жизни, Реджинальд щедро сыпет бравадой о доблести и чести, воодушевляя своими речами окружающих. Он проникается тяжким положением Салазара и несколько месяцев оберегает юного безумца, терпеливо прислушивается к его бредням, а главное — не спорит. Он подыгрывает его иллюзиям, но постепенно направляет их в сторону реальности. Благодаря помощи нового друга Сэлу удается приструнить свои амбиции и устроиться чернорабочим в Жилой Зоне. Пару месяцев он сводит концы с концами, осваиваясь в перипетиях новой жизни, пока Реджинальд не покидает его. Как позже выяснилось, компания незарегистрированных охотников обнаружила логово Крефигциима, не рассчитав своих возможностей."}),(0,s.jsx)(l.p,{children:"В одном из последних писем Реджинальд, будто ожидая конец, расчувствовался, делясь мыслями о потенциале своего подопечного."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.em,{children:'"For alle the wo thou shalt wrek upon this worlde, yet art thou, Salazar, a fīn man still"'})}),(0,s.jsxs)(l.p,{children:["Или иными словами — ",(0,s.jsx)(l.em,{children:'"Несмотря на все горе, что ты принесешь в этот мир, всё же, Салазар, ты остаешься достойным человеком"'})]}),(0,s.jsx)(l.p,{children:"Эта фраза запала Сэлу в душу, хоть и не стала для него божественным откровением. Он не отказывается от своих грандиозных идей, не перестает считать себя величественным. Тем не менее, он наконец осознает, что прежде чем становиться богом второго мира, ему для начала стоит стать заслуживающим уважения грешником. С тех пор мужчина представляется как Салазар Фейнман (Salazar þe fīn man), в память о друге и в знак благодарности за протянутую руку помощи."}),(0,s.jsx)(l.p,{children:"Вскоре жилую зону посещает женщина с маской, что напоминает маску самого Сэла. Лин Дан, уже давно искавшая сородича, рассказывает Салазару о расе фэнхуан и Империи Лунов, чьи дворцы скрыты в небесах. Она помогает ему добраться на территорию Империи Лунов, где молодого феникса тепло встречает Императорский Фэнхуан."}),(0,s.jsx)(l.p,{children:"Вплоть до окончания цикла Солнца (на протяжении около восьми лет), Сэл находится на территории Империи, где ведется серьезная работа по его воспитанию. Он осознает свою принадлежность к роду фениксов и учится сдерживать внутренний огонь. Сообщество фэнхуан быстро замечает странности нового члена семьи, однако списывает их на буйный нрав цикла Солнца. Принимается решение отложить переход новичка в распоряжение чжулун до следующего цикла, пока Императорский Фэнхуан лично не убедится в пригодности феникса."}),(0,s.jsx)(l.p,{children:"Дело облегчается тем фактом, что грешник начинает делать отличные успехи в усвоении философии Империи, её иерархии и роли пневматических рас в устройстве мира. Для Императорского это становится сюрпризом и хорошим знаком, но на деле Сэл лишь продолжает делать то, что практиковал всю свою жизнь. Прислушивался к различным вероисповеданиям и мировоззрениям, пропускал через себя и вырабатывал абсолютно иную модель, удобную для его личных взглядов."}),(0,s.jsx)(l.p,{children:"В какой-то момент за успехи в освоении материала, Салазара награждают памятной вещью – личным дневником предыдущего Стража Огня Исхода – Гао Чжи Вэньлу."}),(0,s.jsx)(l.p,{children:"Следующим же вечером Сэл врывается в покои Императорского Фэнхуана с горящими глазами и пачкой бумаг в руке. Он утверждает, что складки на каждом из листов дневника сложились в символы, в доказательство выкладывая их перед ошарашенным фениксом. На смятой бумажке дрожащей рукой выведена надпись."}),(0,s.jsx)(l.p,{children:"Ситуация выходит курьезной. С одной стороны очевидно, что безумец раздербанил дневник своего предка и помял листки в нужном порядке. С другой стороны, на бумаге записана узкоспециализированная упрощенная запись квеллария, используемая учеными мужами для быстрых заметок (лишь спустя сотни лет она станет “современным” квелларием). Сэл на тот момент не освоил даже обычный квелларий, от того и знать о такой записи не мог. Каким-то чудом выходка сходит ему с рук и обучение продолжается."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 2, Луна 1469 - 1479"})}),(0,s.jsx)(l.p,{children:"При наставлении Лин Дан Салазар проходит медитацию и перерождается в Лунном цикле. Разум феникса очищается и перестраивается на новый лад. Внезапно для себя его прошлое “я” оказывается какой-то иной, совершенно чуждой ему личностью. Он начинает подходить к своим суждениям с позиции логики, а не эмоций, обнаруживая в своих идеях множество слабых мест, которых не замечал ранее. Это состояние переосмысления становится глотком свежего воздуха для тех, кто в то время контактировал с Салазаром. Вспыльчивость и заносчивое поведение улетучиваются. Остаются лишь тихие странности. Так, например, феникс может отвлечься на полуслове, погрузившись в свои мысли, или внезапно перевести тему разговора. Но то было не так важно в общей картине."}),(0,s.jsx)(l.p,{children:"Первое знакомство с семьей драконов не должно было омрачиться, ничего не предвещало беды. Достоверно не известна причина, почему чжулуны отказались от своего нового фэнхуана. Возможно, дело было в слухах о безумии молодого феникса, породивших предвзятость. Возможно, выступление Сэла оказалось не столь идеальным, каким рисовало его воображение."}),(0,s.jsx)(l.p,{children:"«Я смотрел в их глаза и видел бархатные россыпи тягучего презрения. Они взвешивали меня, ставя на противоположную чашу фаянсового идола, коим я не мог быть и не сумею стать даже возжелав того всеми фибрами своей души. В тот миг мне пришло озарение. Словно сами саррары шептали, эхом гуляя в коридорах многовекового мрамора – мне не суждено стать их рабом, я знал это. И они это знали. Лишь одна искра сомнения обрушила помостки той безупречной сцены…»"}),(0,s.jsx)(l.p,{children:"Салазар становится изгнанником. Империя Лун отказывается признавать его существование и закрывает перед ним двери своих дворцов. Вкусивший было плод величия феникс вновь оказывается на самом дне. Разбитый и потерявший всяческое стремление к власти над этим миром Сэл, желая вновь найти себя, решает возвратиться к истокам, давшим начало его пути — церкви. Благодаря полученным за восемь лет пребывания в Империи знаниям и навыкам, ему удается пристроиться послушником в Главный Храм, со временем показывая неплохие успехи в стезе служения предкам."}),(0,s.jsx)(l.p,{children:"Дни в храме проходят размеренно и, за вычетом бытовой суеты, спокойно. Без титанического груза ответственности перед навязанным наследием лунный феникс словно расправляет крылья. Он легче открывается людям, чаще слушает, чем говорит сам и обретает хороших друзей среди послушников. Со временем у него появляется невинное увлечение собирать там и тут материалы и делать из тех всяческие безделушки. Каждому из этих предметов Сэл дает имя, а временами даже описывает характер и особенности “персонажей”, стоящих за его поделиями. Однажды алтарник застает Сэла ведущим философскую дискуссию с самодельной фигуркой Архонта Знамений. Когда феникса окликают, статуэтка поворачивает голову вслед за хозяином."}),(0,s.jsx)(l.p,{children:"Спустя несколько месяцев артифексы храма замечают способность Сэла оживлять предметы и начинают все чаще использовать его в качестве слуги в мастерских. Странное поведение списывают на необходимость в живом воображении для работы редкой цепи. Мастера артефактов и так зачастую являются замкнутыми людьми со своими странностями, поэтому Фейнман быстро приживается."}),(0,s.jsx)(l.p,{children:"Следя за трудами мастеров, Салазар подмечает, что во время работы те наспех записывают информацию не используя формальную запись, вместо этого приводя символы квеллария к упрощенным формам. У всех эти формы слегка отличаются, но общие символы находятся во всех записях. Благодаря этому открытию Салазар наконец понимает, что было зашифровано в дневнике Гао Джи."}),(0,s.jsx)(l.p,{children:"Новое увлечение артефакторикой дает Салазару необходимый импульс и цель, возвращает стремление к достижениям. Он берет курс на становление алтарником, чтобы впоследствии принять должность полноценного артифекса."}),(0,s.jsx)(l.p,{children:"Ради развития понимания устройства мира, он просит старших разрешение изучать архивы храма, а по вечерам отпускать в библиотеку замка, где он погружается в более насущные для грешников темы."}),(0,s.jsx)(l.p,{children:"Спустя годы изысканий, исследования дают неожиданные плоды. В одной из книг в архивах Салазар обнаруживает следующий отрывок."}),(0,s.jsxs)(x,{children:[(0,s.jsx)(l.p,{children:"...И из теней невежества мы сошли в глубины просветления, где истина не ослепляет, но очищает, а звезды шепчут тайны мироздания тем, кто умеет слушать..."}),(0,s.jsx)(l.p,{children:"— Свитки Негласной Триады, Глава XII"})]}),(0,s.jsx)(l.p,{children:"Написанная в 1512 году до нашей эры, несколько раз переиздававшаяся и дополнявшаяся, книга является исторической сводкой о развитии научного сообщества грешников. Урезанным сборником документов и легенд той эпохи, временами противореча сама себе, когда дело касается личностей и их свершений. Отрывок повествует о трех великих артифексах допотопного мира — Энки Намму, Гиль Намтаре и Нинтир Лугаль. По легенде, сами боги подарили им инструменты, с помощью которых мастера ковали могущественные артефакты древности."}),(0,s.jsx)(l.p,{children:"Сама книга при ближайшем рассмотрении оказывается вдоль и поперек наполнена разного рода загадками и шифрами. Разгадывая один, Салазар тут же натыкается на другой. Номера глав складываются в кодовые замки, а слова древних текстов сплетаются в таинственные послания."}),(0,s.jsx)(l.p,{children:"Тропа загадок увлекает Салазара вслед за собой, словно рассыпанные кем-то хлебные крошки. Проводя время за службой в храме, а после гоняясь за своим увлечением, феникс сам не замечает, как подходит последний год цикла. Осознание накатывает на него волной паники, ведь вскоре вернется “он”, тот неудержимый безумец, вновь готовый сломать его жизнь пополам."}),(0,s.jsx)(l.p,{children:"В попытках понять себя перед грядущим перерождением Салазар начинает регулярно молиться Темным Предкам и исповедоваться, практикует Оферту Пневмы и Поток Хюле. Он даже проходит Испытание Шрамов, считая, что его безумие есть шрам на его душе. Подобное рвение впечатляет старших настолько, что те без раздумий дают разрешение на тридцатидневное затворничество молодого феникса."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 3, Солнце 1479 - 1489"})}),(0,s.jsx)(l.p,{children:"По завершению медитации Фейнман ощущает себя пылающим очагом пламени. Энергия бурлящей рекой разливается по его телу, заставляя двигаться, создавать, разрушать. Однако в этот раз Салазар много более сознателен, чем в свой первый цикл. Бушующий пламенем, но смиренный, он меньше зацикливается на своих личных идеях и амбициях, вместо этого направляя поток на окружающий мир."}),(0,s.jsx)(l.p,{children:"Солнечный феникс собирает группу друзей среди младших служащих и подает прошение о паломничестве к святым местам, по той или иной причине несущих прикосновение предков. Эта инициатива дает ему возможность сбежать от душных мастерских, в которые так тянулась его прошлая личность."}),(0,s.jsx)(l.p,{children:"В состав группы входит трое анахоретов, пятеро интердикторов и около пары дюжин младших служителей. Продвигается она размеренно, без спешки, зачастую останавливаясь для проведения ритуалов и проповедей. Тем не менее, многие из новичков впервые сталкиваются с походными условиями и фауной мира в настоящем отдалении от твердыни замка. Салазар всерьез обращает внимание на свою магию огня, как средство противодействия фауне мира. Один из анахоретов, изначально проявлявший симпатию к Сэлу, соглашается обучать того в ходе путешествия."}),(0,s.jsx)(l.p,{children:"Чуть было не стоивший жизни случай произошел, когда группа остановилась у полуразрушенного святилища темных предков. Погружаясь в медитацию среди давно обрушившихся стен масштабного зала, Сэл вдруг осознает себя будто бы в кошмарном сне. Вокруг него ходят люди в религиозных одеждах, исполняя ритуал, происхождение которого уходит в глубины древности почти на тысячелетие. К счастью, молодой фэнхуан знаком с историей места, которое вызвался посетить. Гнозис демонстрирует ему событие 500-ых годов, когда группа служителей, стремясь выжечь грех внутри себя, во время исполнения ритуала использовала в священном напитке ядовитые травы. Салазар вмешивается в процедуру подготовки и с помощью своего дара убеждения берет церемонию в свои руки, завершая её без жертв."}),(0,s.jsx)(l.p,{children:"Пережитый катарсический опыт наводит Салазара на мысли о природе греха."}),(0,s.jsx)(x,{children:(0,s.jsx)(l.p,{children:"…Прискорбно признавать, но в том есть неотъемлемая правда этого мира. Черви роились в моей душе дольше чем я знаю себя и они живут в каждом, кого я встречал на пути. День ото дня они кормятся моими страстями и кошмарами, впиваются в хрупкую плоть естества вновь и вновь ускользая от моего невидящего взгляда. Я слаб, слеп, лишен мудрости, но наделен пламенем очищающим…"})}),(0,s.jsx)(l.p,{children:"Вернувшись в храм, Салазар просит об Обряде Возвращения Глаза. Несколько дней он проводит в подземельях под храмом, доводя себя до состояния иссушенного скелета, а после несколько месяцев молится и постится. Перед его глазами возникают картины прошлой жизни, образы людей, чьи судьбы были разрушены по вине его фанатичных идей и деяний. Салазар принимает свои грехи как тяжкий груз прошлого. Отныне он видит свою грешную сущность и не отворачивается от нее. Когда Сэл наконец получает право вернуться в мастерскую артифексов, товарищи по делу замечают, что глаза феникса сияют ярче обычного."}),(0,s.jsx)(l.p,{children:"В его словах появляется сила. Сам образ мужчины будто бы возвышается, вселяя уверенность в сослуживцев и старших. Яркие, инновационные идеи находят одобрение среди мастеров артефакторики, укрепляя статус молодого алтарника в коллективе. Вскоре Салазару дозволяется спуститься в залы Геометрического Ковчега, чтобы получить полноценное звание Артифекса Анмемарей."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 4, Луна 1489 - 1499"})}),(0,s.jsx)(l.p,{children:"Вновь “переродившись”, Салазар ударяется в исследование оставленного Гао Чжи Вэньлу дневника. При использовании инструментов артифексов становится очевидно, что каждый сантиметр бумаги испещрен тайными знаками, формулами и зацепками. Вероятно, в свои последние циклы Гао окончательно сошел с ума, погруженный в теории заговора и собственные иллюзии. Неудивительно, что чжулуны так болезненно отреагировали, узнав, что новый фэнхуан безумен прямо с порога."}),(0,s.jsx)(l.p,{children:"Сэл, тем не менее, оказывается увлечен оставленным ему материалом по уши. В его глазах конспирологическая вакханалия записей предка представляет собой четко организованное руководство по методологиям сокрытия информации. В хаосе слов и чисел феникс видит подсказки, намекающие на самые разные уголки Энкража. Интересно, что найденная в библиотеке книга содержала координаты, пересекающиеся с заметками Вэньлу. Сэл предполагает, что как в книге, так и в дневнике предка, заключены маршруты-пустышки и лишь пересечение двух множеств дает достойные исследования точки интереса."}),(0,s.jsx)(l.p,{children:"Несколько лет феникс выживает. Он укрепляет свои знания, расширяет влияние в коллективе и закаляет свое тело, развивая магические цепи. Вокруг него формируется круг знакомых и друзей – членов Анмемарей и талантливых гостей замка. Объединяют их стремление к раскрытию тайн этого мира и исследование природы грешников. В знак единства, группа называет себя ярко и амбициозно – “Корпус Прозрения”."}),(0,s.jsx)(l.p,{children:"Спустя примерно десять лет после предыдущего паломничества, он выдвигает новый проект, на этот раз несущий более практичные цели. Помимо посещения святых мест послушниками, предлагается сбор ресурсов для артефакторики и помощь Анахоретам в миссионерских проповедях. Во время путешествия он время от времени просит отряд задержаться в нужных ему местах."}),(0,s.jsx)(l.p,{children:"Расследуя одну из таких точек – ничем не примечательную поляну – Салазар, следуя намекам Гао, вычерчивает на земле символику Темных Предков и внезапно для себя оказывается в каменном зале. Надписи на монументальном обелиске в центре гласят, что выйти грешник сможет, лишь потеряв память либо согласившись принять пакт, запрещающий раскрывать тайны древности. Это объясняет, почему Гао не мог явно сообщить потомку маршрут к найденному им древнему залу – прямое раскрытие тайны грозило фениксу гибелью под действием таинственной магии. Коснувшись обелиска, Фейнман принимает пакт, и перед ним открывается магическая дверь, плотно очерченная мелкими иероглифическими символами. В дальнейшем изучив эти символы, фэнхуан узнает в них руководство по сборке одного из инструментов артифексов прошлого – аурометра – и, что самое главное, калибровочный код, настраивающий предмет на точно выверенный спектр проклятой энергии. В комбинации это позволяет видеть тайные надписи, которые, как выясняется, все это время были нанесены по всей территории нижнего мира в самых неожиданных его уголках."}),(0,s.jsx)(l.p,{children:"Через некоторое время экспедиция делает двухмесячную остановку в жилой зоне. Салазар использует инструменты местных мастеров для сборки простейшего аурометра, позволяющего видеть потоки проклятой энергии разных аспектов. Он с любопытством осматривает жилую зону и окрестности, восхищаясь удивительными завихрениями магии окружающего мира. Проходя мимо реки на северной окраине зоны, феникс замечает, что течения воды ответвляются, уходя вглубь под землю."}),(0,s.jsx)(l.p,{children:"Салазар приглашает своих товарищей из “Корпуса” и неделю раскапывает участок у реки, пока наконец из толщи почвы не вырывается столб воды. Время стоянки растягивается до полугода, за которые группа увлеченных грешников прокладывает трубопровод до жилой зоны. Сердца абсалонда вставляются в специальные слоты, обеспечивая грешников чистой питьевой водой."}),(0,s.jsx)(l.p,{children:"По завершению экспедиции, в награду за исполнение действительно важного для благополучия жилой зоны проекта, “Корпус Прозрения” получает почетное приглашение в Научную Ассоциацию. Закономерно, группа распадается. Часть из членов принимает приглашение и расходится по отделам, не обрывая при этом контактов с Салазаром. Основной костяк, вместе с самим фениксом, входит в состав Сектора Артефактной Экспертизы."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 5, Солнце 1499 - 1509"})}),(0,s.jsx)(l.p,{children:"Знакомясь со много более опытными коллегами, Салазар учится продвинутым методикам создания магических предметов. В качестве научной работы он ведет поиски артефакта, наиболее оптимального для Обряда Древнего Эха. От Императорского Фэнхуана он слышал о “поющих витражах”. Разноцветных магических стеклышках, в свете небесных тел издающих звук, резонирующий с остальным стеклом. Это наводит его на мысль, что стекло является хорошим проводником и резонатором. Подобные идеи подтверждают записи других исследователей того времени."}),(0,s.jsx)(l.p,{children:"Феникс решает провести ритуал, используя зеркала различных форм и магических характеристик. В попытках связаться с Архонтом Знамений он замечает, как разные опытные образцы зеркал начинают резонировать между собой. В то же время в Храме проходит несколько ритуалов Слияния Эхосов. Салазар вызывается присутствовать на них и с помощью аурометра отслеживает потоки энергии между двумя грешниками. Он замечает, как энергетические ритмы крови синхронизируются во время обряда и предполагает, что связь Эхоса функционирует через медиум в лице чистой энергии. После ряда экспериментов выясняется, что проклятая энергия также может передавать колебания разной частоты и у феникса получается соединить два устройства наподобии того, как соединяются души двух возлюбленных."}),(0,s.jsx)(l.p,{children:"Вскоре феникс заканчивает разработку эхо-зеркала. Компактного артефакта, способного передавать изображение и звук."}),(0,s.jsx)(l.p,{children:"Эта работа, хоть и является успешной разработкой, оставляет неприятное послевкусие в душе Салазара. Да, он любит мастерить интересные вещи, однако на этом поприще ему суждено навсегда остаться простым ремесленником. Феникс же хочет оставить след в истории."}),(0,s.jsx)(l.p,{children:"В поисках действительно заманчивых направлений он подает прошение о переводе в Сектор Одиль. Этот отдел, ассоциирующийся с Архивариусом Современности и отвечающий за передовые, рискованные разработки, в тот период находился в упадке по причине строгой консервативной политики Верховного Арбитра и самого Архивариуса. Вливание новой крови вызвало одобрение со стороны прогрессивного научного состава организации."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 6, Луна 1509 - 1519"})}),(0,s.jsx)(l.p,{children:"Исследования скрытых под завесой мира тайн тем временем дают свои плоды. Салазар проходит то, что называют “Вторые врата Ха’ары” и обнаруживает древнюю библиотеку, а также личную лабораторию одного из древнейших членов научного сообщества Третьего Мира — Энки Намму. К своему сожалению, феникс убеждается, что Коллекция Энки была архаичной еще при его жизни. Большинство записей выполнены на древнем квелларии, аккадском, арамейском, финикийском и прочих языках давно ушедших эпох. В одном из отделов зала знаний Сэл находит десять сложенных в ряд свитков, содержащих одинаковый текст на десяти различных языках. Одним из этих языков, к великой радости Салазара, оказывается знакомый ему иврит. Символы открывают настоящее сокровище. Карту к наследию мудреца. Легендарное кольцо, одно из составляющих алхимической машины, сотворенной самими богами. Тиферет Махут. Величие Сущности. Стремящийся оставить свое наследие в надежных руках Энки разобрал легендарный артефакт на части и захоронил в разных регионах Энкража. Свою же библиотеку он спрятал за невидимой стеной из загадок и намеков. Тысячи лет грешники подбирались к его тайне, зашифрованными письменами передавая свои изыскания следующему поколению. Гао Вэньлу не смог добраться до награды, но оставил преемнику свои труды в надежде, что ключ к великому замку наконец будет найден."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 7, Солнце 1519 - 1529"})}),(0,s.jsx)(l.p,{children:"К своему удивлению, Салазар обнаруживает, что за многие века грешники в своих исследованиях Энкража успели отыскать несколько частей Тиферет. Пять элементов конструкции кольца уже находятся в архивах НАЭ и проходят по номенклатурам как допотопные артефакты различных назначений."}),(0,s.jsx)(l.p,{children:"Феникс тут же выдвигает прорывную теорию, что между пятью экспонатами архивов может быть связь. Он показательно запрашивает данные о местах их раскопок и выдержав паузу в пару месяцев заявляет, что видит закономерности в пяти случайных точках на карте и может предсказать координаты шестой детали. Архивариус Древности того времени проникается такой наглостью и одобряет экспедицию. Ресурсы НАЭ позволяют Салазару целенаправленно следовать инструкции Энки, иногда намеренно допуская ошибки, но рано или поздно достигая цели."}),(0,s.jsx)(l.p,{children:"В ходе экспедиции Салазар обнаруживает небольшой культ, практикующий поклонение Теневому Пауку. Время от времени прилетая на сборища еретиков, феникс под покровом скрывающей личность магии начинает проповедовать свои личные идеи, адаптируя их под реалии Энкража."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 8, Луна 1529 - 1539"})}),(0,s.jsx)(l.p,{children:"Все 311 деталей Тиферет добыты и выставлены на обозрение перед ошеломленной публикой. Никто в НАЭ не имеет ни малейших догадок о том, как сделать разделенное снова целым. Даже Салазар. В своем зале знаний Энки оставил подробную иллюстрированную инструкцию по возврату легендарного артефакта в первоначальное состояние. Однако устройство механизма настолько запутанно и подчиняется настолько тонким законам мира, что Салазару требуется невероятный объем теоретических выкладок, расчетов, экспериментов, проб и ошибок, лишь чтобы сделать малый шаг на пути к прогрессу. Долгие десять лет уходят на сбор частей воедино."}),(0,s.jsx)(l.p,{children:"В итоге, когда Тиферет Махут снова становится единым целым, артефакт на мгновение активируется, резонирует с магической цепью Салазара, а затем потухает и перестает реагировать на сигналы. Чувствительные к силе легендарного оружия ученые в один голос заявляют, что Тиферет действительно ожил, но лишь по ему ведомым причинам перешел в режим ожидания. Салазару ничего не остается, как передать находку обратно в архив."}),(0,s.jsx)(l.p,{children:"Впрочем, труды не проходят бесследно. За проделанную монументальную работу в 1537 году Салазар получает почетное звание Эвритария и руководителя Сектора Одиль."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 9, Солнце 1539 - 1549"})}),(0,s.jsx)(l.p,{children:"Пламя Огня Исхода с каждым циклом все сильнее разгорается в глазах феникса. Он начинает видеть метания грешных душ, их страхи и сомнения. Пользуясь этой силой, Салазару удается взять в руки лидерство в культе Теневого Паука. Собрания этого сообщества становятся своеобразной отдушиной, где феникс может проповедовать свое видение мира и религии."}),(0,s.jsx)(l.p,{children:"Он вдохновляется историческими хрониками о периоде правления Архимандита Шешкала и начинает подражать ему. Используя свои способности к иллюзии и разработанные им эхо-проекторы, он появляется перед культистами во вспышках пламени, устраивает хитроумные проверки на верность и публичные наказания. Те, в свою очередь, лишь уверяются в могуществе и божественном происхождении своего лидера."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 10, Луна 1549 - 1559"})}),(0,s.jsx)(l.p,{children:"Салазар решает использовать культ себе на пользу. Текущий Архивариус Современности Еремия Светлый представляет собой ходячую древность возрастом более 800 лет, с ослабевшим ЭПФО и провалами в памяти. Фениксу кажется забавной идея немного поразвлечь дедулю и вместе с тем получить полезную информацию. Он подсылает к Еремии молодую грешницу Милим, участницу культа, чья энергетика совместима с архивариусом."}),(0,s.jsx)(l.p,{children:"Старик легко проглатывает наживку и Салазар начинает экспериментировать с этой маленькой авантюрой. Однажды он вручает своей подчинённой кальян, содержащий экспериментальный галлюциногенный препарат, разрабатываемый в одном из отделов. Все идёт не по плану, когда галлюциноген вызывает у Еремии приступ воспоминаний древности. Старик видит вокруг себя мрачных эйдолонов и призывает мощную гравитационную аномалию, которая обрушивает потолок кабинета, убивая Милим на месте. Ядро Иеремии не выдерживает перегрузки и разрушается. Препарат в кальяне улетучивается не оставляя следов."}),(0,s.jsx)(l.p,{children:"Узнав о происшествии Салазар является к культистам в виде призрака погибшей Милим, которая сообщает о прискорбной гибели их лидера по вине сверхъестественных сил. В качестве проводов устраивается недельная оргия, с применением изменяющих сознание веществ. Когда всадники Дикой Охоты прибывают по следу Милим, озлобленные культисты принимают их за демонов и нападают, вынуждая хранителей правопорядка применить силу. Когда задержанные выходят из наркотического бреда, их показания противоречат друг другу."}),(0,s.jsx)(l.p,{children:"На последующем голосовании эдитеронов в 1557 году принимается решение выдвинуть на пост Архивариуса Современности молодого и амбициозного грешника – Салазара."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 11 – 15, 1559 - 1609"})}),(0,s.jsx)(l.p,{children:"Получив должность Архивариуса Салазар наконец чувствует себя на своем месте. Драгоценный Сектор Одиль с каждым годом пополняется яркими умами, лояльными фениксу. Фейнман чувствует, что теперь он способен привнести в мир нечто значимое, однако консервативная и строго бюрократическая сущность Верховного Арбитра все еще вставляет ему палки в колеса. Архивариус занимает публично нейтральную позицию, однако по возможности поддерживает прогрессивные настроения."}),(0,s.jsx)(l.p,{children:"«…Костлявая рука болотистой канцелярщины все еще висела на шее храма знаний. Важнейшим моим трудом в те годы стало пытливое изыскание выхода из сложившегося положения. Я дергал за все подвластные мне нити в слепой надежде, что одна из них обрушит пыльный стеллаж на гниющую рыбью голову…»"}),(0,s.jsx)(l.p,{children:"В попытках найти поддержку в уже знакомой инстанции, Салазар развивает свое положение в Анмемарей. Он посещает важные мероприятия, помогает в проведении ритуалов и обрядов. Пользуясь дружбой с высокопоставленными членами Анмемарей он проходит посвящение Аполитрозиса. Феникс самонадеянно отказывается от наставника и входит в гнозис один."}),(0,s.jsx)(l.p,{children:"На этот раз искажение оказывается не таким простым. Оно рисует события из истории культа Режущих, славящихся высокой степенью секретности. Не обладая информацией об истории скрытной организации, феникс оказывается сбит с толку и допускает ряд ошибок. Ему приходится провести тщательное расследование, в результате которого он убивает персону, в которой подозревает предателя. Это вызывает разрушительное закрытие гнозиса, в котором Сэл получает ранения, но выживает."}),(0,s.jsx)(l.p,{children:"В 1607 году, благодаря доступу в секретные отделения Архива Древности, Салазар находит исторический справочник о культах “Феникса”, в деталях описывающий структуру организаций, существовавших на протяжении всей истории Энкража. Используя ресурсы секторов Эзохроники и Одиль, Салазар разворачивает по всему Энкражу несколько кампаний, привлекающих грешников похоти. Каждая из них использует различные идеологии, призванные влиять на разные аспекты существования обитателей второго мира. Спустя около двадцати лет между группировками начинаются идеологические конфликты. Сообщества сталкиваются друг с другом, распадаются, сливаются, дробятся на части. В отчетах этот проект будет отмечен как “Озеро Секунд”. Первое время проект курируется лично Салазаром, однако со временем молодой теолог по имени Меир Коген все больше вовлекается в исследование, собирая и анализируя данные самостоятельно."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 16, Луна 1609 - 1619"})}),(0,s.jsx)(l.p,{children:"Используя дорогое и зачастую экспериментальное оборудование, поставляемое Сектором Одиль и собираемое им самим, Салазар успешно сопровождает Экзоциархов в гнозисах, существенно увеличивая шансы на успех и выживаемость групп зачистки."}),(0,s.jsx)(l.p,{children:"Этот период характеризуется разработкой кристаллов памяти. Устройства на их основе позволяют записывать информацию о событиях прошлого и выводить её при помощи миниатюрных эхо-проекторов в виде удобных подсказок. Также в этот период к Сектору Одиль присоединяется Серафина Розен. Обладающая легендарным орудием грешница становится лидером экспедиций за бастионы. Являясь близким другом Салазара и других членов организации того времени, она дает организации так необходимое в те времена ощущение силы и значимости, вселяя в сердца Сектора надежду на будущие свершения."}),(0,s.jsx)(l.p,{children:"В 1612 году усилия по закреплению положения в Анмемарей получают неожиданный оборот. Сестра-фенхуан Лин Дан, выступающая для Фейнмана уважаемой наставницей, в одной из бесед упоминает о своей дружбе с Аглаей Лучезарной и предлагает свои рекомендации на должность Попечителя Храма Предсказаний. Видя в этом возможность получить расположение текущего Архимандита, Фейнман соглашается."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 17, Солнце 1619 - 1629"})}),(0,s.jsx)(l.p,{children:"Инициатива “Озера Секунд” наконец приходит к конечной точке. Все экспериментальные сообщества грешников либо распались, либо слились в одно целое. Меир Коген представляет Салазару результаты теологической работы по доктрине результирующего культа. Фейнман хвалит своего сотрудника и объявляет переход к следующей стадии. В сообществе проводятся фиктивные выборы лидера, в которых побеждает принявший чужое обличье феникс."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 18-19, 1629 - 1649"})}),(0,s.jsx)(l.p,{children:"В 1630 году Салазар от лица Сектора Одиль представляет результаты “Озера Секунд” Бальтазару Крюгеру и Аглае Лучезарной. Эта встреча становится кульминацией почти двухсотлетней работы Салазара. Позиции Архивариуса НАЭ и Попечителя Храма Предсказаний Анмемарей позволяют найти точки взаимодействия с руководителями двух абсолютно разных по своей сути инстанций. После долгих переговоров утверждаются положения нового сообщества, несущего функции благотворительной поддержки грешников, предварительной кадровой подготовки и создания платформы независимых исследований, разбивая застой научного сообщества. Получившееся сообщество решено назвать Тройственным Узлом."}),(0,s.jsx)(l.p,{children:"Получив согласование о местоположении штаб-квартиры новой организации, Салазар лично выполняет ритуал призыва Предрассветного Телестериона. Происходит это в сезон поклонения Теневому Пауку, и в момент ритуала Салазар призывается в Пирамиду Хеопса, где зверь греха признает его лидером культа Похоти и посвящает в Теневые Прядильщики."}),(0,s.jsx)(l.p,{children:"Также в конце цикла Салазаром разрабатывается эхо-платформа. Артефакт, позволяющий фениксу передавать свою иллюзорную проекцию на большие расстояния и на большой площади. Эти платформы устанавливаются в Телестерионе, Архивах и Храме Предсказаний, позволяя фениксу контролировать каждый аспект работы подведомственных организаций."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 20, Луна 1649 - 1659"})}),(0,s.jsx)(l.p,{children:"Спустя десятилетия Салазару удается расшифровать часть материалов библиотеки Тиферет. Энки указывает на местоположение личной библиотеки своего коллеги – Гиль Намтара, талантливого механика и обладателя артефакта Нецах Да’ат. Ключ к библиотеке оказывается за пределами бастиона, и Салазар обращается к Серафине Розен для организации экспедиции, которая оборачивается катастрофой. Ключ к шифру удается изъять из хранилища, но отряд подвергается атаке пустых, которые пожирают всех его членов. Серафина защищает Салазара ценой своего легендарного оружия и едва не лишается жизни. Фейнману удается сбежать, приняв форму феникса, а также унести с собой растерзанное тело Серафины. Грешница лишается руки и ноги, но воля к жизни в ней не утихает. Члены Сектора Одиль сокрушены утратой и дают клятву помочь подруге."}),(0,s.jsx)(l.p,{children:"В библиотеке Намтара полноценной карты деталей Да’ат не обнаруживается, однако некоторые документы содержат явне редакции, выполненные иными чернилами и подозрительно знакомой символикой. Еще одна загадка."}),(0,s.jsx)(l.p,{children:"Также внимание Салазара привлекают чертежи магических механизмов, разбросанных по всей мастерской древнего ученого. Изучение их осложняется тем, что наложенный на хранилища знаний магический пакт запрещает исследовать наследие Намтара кому-либо кроме посвященного в таинства — Фейнмана. С этих пор феникс в тайне ото всех посещает библиотеку, в попытках раскрыть секреты инженерии допотопных времен."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 21 - 22, 1659 - 1679"})}),(0,s.jsx)(l.p,{children:"После пары десятилетий изучения трудов Намтара Салазару удается собрать механическую птицу, приводимую в движение магией аниматроники. Феникс держит её при себе, с удовольствием играя с механизмом, заставляя его двигаться все более и более естественно. Однако на такие игры уходит достаточно много энергии, поскольку двигать шестерни приходится собственной магией. Постоянный источник питания описывается Намтаром в терминах кватернионов, как набор операций над четырехмерным векторным полем проклятой энергии. Мало сказать, что Салазар не понимает этого. Он даже не воспринимает написанное как математику, и в целом как то, что способен осознать человеческий разум. В те времена вся НАЭ живет в терминах евклидовой геометрии, отчего попытки сыскать помощь оказываются тщетны. Фейнману удается вычленить простейшую модель циркуляции проклятой энергии аспекта Воздуха в замкнутом контуре, но произвести расчет феникс оказывается не способен. Он начинает выдавать части этой задачи стажерам и младшим научным сотрудникам Сектора под видом проверки знаний."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 23, Солнце 1679 - 1689"})}),(0,s.jsx)(l.p,{children:"В 1683 перерождается Готфрид Вайгель — современник Лейбница, талантливый математик, механик и философ. Молодой грешник слаб телом, но его разум невероятно блестящ. Салазар моментально замечает талант и склоняет Готфрида к научной работе. Он выдает ему задачу Намтара со словами: “Лишь тот, кто способен выполнить этот расчет, достоин зваться мастером артефакторики”."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 24, Луна 1689 - 1699"})}),(0,s.jsx)(l.p,{children:"В 1695 году Готфрид врывается в кабинет Салазара с кипой бумаг в руках и горящими глазами. Молодой ученый заявляет, что решил поставленную задачу, чем вызывает моментальное недоверие. В отличие от исследователей, пытавшихся решить задачу аналитически, Вайгель воспользовался модифицированным методом аппроксимации Мадхавы из Сангамаграмы, что позволило избежать огромного пласта вычислений, схлопнув ряд функций до констант в частных случаях, ценой точности финальной модели."}),(0,s.jsx)(l.p,{children:"Салазар забирает труды Готфрида “для проверки” и всего лишь за год собирает грубую модель элементального ядра. Вайгель удостаивается звания полноправного научного сотрудника и чести дать имя основанному на его открытии изобретению. Ядро работает на энергии Воздуха, за что получает получает имя Ätherkern. Технологию магических механизмов на базе элементальных ядер Готфрид называет runenwerk."}),(0,s.jsx)(l.p,{children:"Это открытие вызывает резонанс среди сотрудников Сектора Одиль. Они принимают решение не публиковать результаты исследований, вместо этого перенося разработку руненверка на платформу Тройственного Узла."}),(0,s.jsx)(l.p,{children:"Параллельно с этим круг приближенных ведет разработку механических протезов для Серафины Розен. Девушка охотно принимает участие в экспериментах и её тело развивает цепь, позволяющую эффективно контролировать устройства, используя те не только в качестве замены утраченных частей тела, но и как смертоносное оружие."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 25, Солнце 1699 - 1709"})}),(0,s.jsx)(l.p,{children:"В этот период Салазар замечает присутствие в Энкраже научной организации “Скуола Святого Знания” ведущую шпионаж, подрывную и диверсионную деятельность в отношении НАЭ. Влияние её недостаточно велико, чтобы всерьез раззадорить феникса. В целом он решает оставить эту проблему на откуп Реальтам, но время от времени и сам наводит справки о проблемном сообществе, вырабатывая план подрыва конкурентов."}),(0,s.jsx)(l.p,{children:"Многочисленные эксперименты над связанными Узла порождают разнообразие прототипов артефактов. В 1703 году НАЭ заключает сделку с Черным Рынком по сбыту продукции, что позволяет Узлу войти в период процветания, расширяя возможности и влияние."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 26-27, 1709 - 1719"})}),(0,s.jsx)(l.p,{children:"Сектор Одиль начинает отправлять регулярные экспедиции на поиски частей Нецах Да’ат. К 2010 году большая часть из них будет обнаружена."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 28, Луна 1729 - 1739"})}),(0,s.jsx)(l.p,{children:"В 1730 году луны насылают катаклизмы на четыре стороны света. Салазар использует резонанс от этого явления, чтобы получить финансирование на эксперименты по производству зефирита, а также подчеркнуть важность разработок дальнобойного вооружения."}),(0,s.jsx)(l.p,{children:"В тот же год ситуация со Скуолой внезапно разрешается сама собой. Филокрит Антиохис, один из основополагающих членов организации, прибывает в НАЭ, где перехватывается Салазаром и допрашивается. Выясняется, что после казни руководителя, организация самоуничтожилась, причем не без помощи Филокрита. Видя в грешнике талантливого союзника, феникс заводит дружбу с амбициозным ифритом и помогает ему продвинуться на высокий пост в НАЭ."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 55, Солнце 1999 - 2009"})}),(0,s.jsx)(l.p,{children:"За сотни лет перерождений личность феникса изменяется. Изначальное безумие все еще подтачивает его разум, но проявления его подавлены, стерты переходами циклов и вековым опытом, ожидая прихода разрушительной для разума болезни фениксов. Ценности Салазара отошли от завоевания мира, перевоплотившись в любовь ко всему созданному им за все это время. Этот период характеризуется в его жизни переосмыслением своих ценностей и идеалов."}),(0,s.jsx)(l.p,{children:"Он пишет в своем дневнике:\n«…Течение времени берет свое, но и щедрость его не знает границ. Мой путь был долог и все же далек от начертанного завершения. Я ползал червем и воспарил птицей. Блуждал непутевым сыном, потерянным, не видящим дороги, мнящим себя прозревшим. Следом, воспылал духом созидающим. Теперь же приходит пора взять на плечи бремя отца…»"}),(0,s.jsx)(l.p,{children:"В 1999 году феникс заключается контракт со Сталкером и получает трех подопечных из верхнего мира."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 56, Луна 2009 - 2019"})}),(0,s.jsx)(l.p,{children:"С приходом 21 века Салазар находится в положении стабильности и умиротворения. Он состоялся как изобретатель, руководитель и проповедник. Научная ассоциация наращивает темпы новых разработок. Анмемарей, как и прежде, хранит память прошлого. А Тройственный Узел успешно работает во имя высшего блага путем незначительных ”компромиссов”. Феникс посещает своих связанных, следит за благополучием избранных членов подведомственных структур. Его усилия более не движимы стремлением к личному утверждению. Теперь он лишь размеренно взращивает сад, построенный его руками на протяжении веков."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"— Цикл 57, Солнце 2019"})}),(0,s.jsx)(l.p,{children:"В январе 2019 года Салазар завершил переход в цикл Солнца. Из-за привычной процедуры перестроения он выпал из потока событий, но сейчас он наконец вернулся в строй и готов встретиться с силами, вновь угрожающими этому миру."})]})})]}),(0,s.jsxs)(r,{title:"Дополнительно",children:[(0,s.jsx)(r,{title:"Факты о персонаже",children:(0,s.jsxs)(h,{children:[(0,s.jsx)(d,{title:"Цикл",children:(0,s.jsx)(l.p,{children:"На момент вступления в игру завершил свою медитацию перехода в 57-ой цикл Солнца. Процесс перерождения помешал персонажу вмешаться в трагические события последних дней."})}),(0,s.jsx)(d,{title:"Осведомлённость о Верхнем Мире",children:(0,s.jsx)(l.p,{children:"Наподобие Анжелии Вайтгрейв, Салазар, хоть и является древним грешником, очень хорошо осведомлен о мире живых. Политика Тройственного Узла в отношении молодых грешников и, в меньшей мере, посещение связанных, позволяет Архивариусу Современности быть в курсе самых специфических трендов. Феникс знает, что такое интернет, прекрасно понимает сленг грешников современности и время от времени создает артефакты, напоминающие устройства Верхнего Мира."})}),(0,s.jsx)(d,{title:"Вокал",children:(0,s.jsx)(l.p,{children:"Поет чувственным баритоном, переходящим в бас. Благодаря магии маскировки может имитировать в принципе любой певческий голос, что позволяет показывать забавные сценки с мюзиклом одного человека. Видят их, конечно, лишь избранные."})}),(0,s.jsx)(d,{title:"Безделушки",children:(0,s.jsx)(l.p,{children:"Помимо артефактов любит мастерить забавные безделушки. Процесс помогает фениксу сосредоточиться на своих мыслях, и морально разгрузиться после тяжелого дня в архивах, храме или Телестерионе."})}),(0,s.jsx)(d,{title:"Публикации в Эфемерид",children:(0,s.jsx)(l.p,{children:"Пишет научные статьи в “Эфемерид”. Временами делает это под разными псевдонимами, заставляя выдуманных им ученых вступать в дискуссии от издания к изданию. Вишенкой на торте становятся ситуации, когда к дебатам подключаются реальные члены НАЭ."})}),(0,s.jsx)(d,{title:"Профессиональный статус",children:(0,s.jsx)(l.p,{children:"Салазар является Архивариусом Современности НАЭ, Попечителем Храма Предсказаний Анмемарей, основателем и лидером Тройственного Узла, а также лидером культа Похоти в статусе Теневого Прядильщика."})})]})}),(0,s.jsx)(r,{title:"Внешность",children:(0,s.jsxs)(j,{children:[(0,s.jsx)(l.p,{children:"У Салазара белые волосы с лёгкой волной, чуть взъерошенные и подстриженные так, чтобы они свободно обрамляли лицо. Вблизи висков видны пряди разной длины, придающие причёске динамику, а над лбом волосы чуть приподняты, открывая лоб. Лёгкая небритость и аккуратная, короткая борода подчёркивают благородные черты: скулы отчётливо выражены, подбородок твёрдый, а губы чётко очерчены. Глаза же сразу выдают его происхождение из расы фэнхуан: это Взгляд Огня Исхода, при котором радужка светится золотым сиянием. В уголках глаз порой проступают тонкие «прожилки» света, словно золотые слёзы, указывающие на внутреннюю силу и связь с магической сущностью фениксов."}),(0,s.jsx)(l.p,{children:"Его монументальная фигура, возвышающаяся примерно на два метра, внушает уважение и командует вниманием. Телосложение Салазара массивное и внушительное, что доказано его пятисотлетними тренировками. Мускулы его тела пропорционально развиты и не утратили своей силы с годами. Его плечи широкие, грудная клетка глубокая, в целом тело имеет вид мощной, хорошо сложенной античной скульптуры. Всё это создает впечатление надежности и защиты, ведь даже в цикле Луны, когда его черты смягчаются, его физическая сила остаётся величественной и теплой, создавая атмосферу доверия. В цикле Солнца, когда его лицо приобретает строгость и решимость, он выглядит как защита от всех бед: притягивает восхищённые взгляды и служит примером для идущих за ним. Его уверенность отражается не только в выражении лица, но и в осанке — Салазар всегда стоит прямо, его грудь немного приподнята, взгляд уверен и наполнен силой. В периоды спокойствия цикла Луны его лицо смягчается, взгляд становится теплее, словно излучая свет и гармонию."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"Одежда"})}),(0,s.jsx)(l.p,{children:"Повседневная одежда Салазара — это синтез строгой униформы и ритуального облачения. Его облачение выполнено из плотной чёрной ткани с матовым блеском, идеально подогнанной по фигуре. Прямой двубортный китель с узкими лацканами украшен тонкими золотыми кантиками по швам, а манжеты застёгнуты на запонки с символами Анмемарей. Плотная ткань аккуратно облегает широкие плечи и руки, подчёркивая рельеф бицепсов и крепость предплечий, но без излишней демонстративности. Высокий воротник подчёркивает благородные черты лица, а ряд аккуратных пуговиц из чернёного металла придаёт образу завершённость. Сверху он носит лёгкую ритуальную накидку, похожую на ризу, из золотистой ткани, расшитую священными символами и тонкими линиями диаграмм на квелларии. Мягкие складки лёгкой ткани контрастируют с чёткими линиями униформы, создавая баланс между строгостью и духовным величием. Даже когда он просто стоит, в его облике чувствуется энергия: мускулы подчинены дисциплине, каждый жест выверен, а присутствие внушает спокойную уверенность тем, кто рядом. Накидка легко отстёгивается или сворачивается, чтобы не мешать при работе в архивах. В зависимости от цикла фэнхуан, на груди Салазара сияет брошь в виде символа Тёмного Солнца или Тёмной Луны, дополняя образ. Завершают ансамбль высокие ботинки из чёрной кожи с утончёнными золотыми вставками, подчеркивающими каждое его движение."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"Маска"})}),(0,s.jsx)(l.p,{children:"Маска Салазара — это воплощение его могущества как религиозного лидера и мудрости как архивариуса, сочетание монументальности и тайны. Её форма чётко очерчена, линии строгие, но не агрессивные, будто сама маска — это печать, закрывающая и оберегающая бездонный колодец знаний. При помощи магии иллюзии Салазар может заставлять маску исчезнуть, открывая его черты лица. Это признак расположения и доверия."}),(0,s.jsxs)(l.ul,{children:["\n",(0,s.jsxs)(l.li,{children:[(0,s.jsx)(l.strong,{children:"В цикл Солнца"})," маска выполнена из чёрного металла с матовой текстурой, что придаёт ей глубину, словно смотрящий в неё может утонуть в тенях. Золотые узоры пересекают поверхность, образуя изящные симметричные паттерны. Вокруг глаз — более сложный орнамент, создающий ощущение короны или нимба, но без излишней торжественности. По обе стороны от висков закреплены тонкие золотые цепочки, звенящие при движении отголосками древних молитв. Глаза маски чуть прищурены, выражение строгое, внушающее уважение и уверенность, словно Салазар видит не только настоящее, но и будущее."]}),"\n",(0,s.jsxs)(l.li,{children:[(0,s.jsx)(l.strong,{children:"В цикл Луны"})," маска трансформируется, металл темнеет до глубокого синего, словно ночное небо, а золотые узоры становятся серебристыми, как лунный свет. Плавные линии орнамента текут по поверхности маски, будто водяные струи, соединяя священные символы с загадочными, почти эфемерными узорами. Около глаз линии расширяются, создавая мягкий, приглашающий образ, как если бы маска сама звала заглянуть в её тайны. Цепочки заменяются тонкими подвесками в форме звёзд, которые тихо звенят, как капли росы. Маска в этот период создаёт ощущение, что Салазар не только хранит знания, но и делится ими, окутывая теплом и мягким светом."]}),"\n"]}),(0,s.jsx)(l.p,{children:"В ожидании великолепного превращения, пока юркие автоматоны мельтешат и скрипят шестернями, переходя в походный режим, а зачарованные одежды скользят по могучему телу, давая тому волю и исчезая из виду, в эти мгновения можно застать феникса в состоянии частичной трансформации. В цикл Солнца Салазар предстает пылающим колоссом, полным решимости и готовым встречать ошеломленные взгляды тлея жаром самоуверенности. В цикл Луны же переходный облик Фейнмана скрывается шелковым полотном иллюзий, рисующих пробирающую до дрожи картину исполина синего пламени."}),(0,s.jsx)(l.p,{children:(0,s.jsx)(l.strong,{children:"Истинный облик феникса"})}),(0,s.jsx)(l.p,{children:"Истинный облик феникса возвышается до 10 метров, с размахом крыльев примерно 18 метров. Он воплощает в себе циклическую мощь и трансформацию, отражающую могущество Стража Огня Исхода."}),(0,s.jsxs)(l.ul,{children:["\n",(0,s.jsxs)(l.li,{children:[(0,s.jsx)(l.strong,{children:"В цикл Солнца его оперение"})," — яркая симфония алых перьев, каждая из которых словно оживает, источая пламя насыщенного алого цвета, напоминающее пылающий факел, неся в себе силу возрождения и решимость. Глаза пылают огненно-красным светом, излучая волю и мудрость."]}),"\n",(0,s.jsxs)(l.li,{children:[(0,s.jsx)(l.strong,{children:"В цикл Луны феникс преображается"}),": его перья становятся бархатисто-синими, переливаясь холодными отблесками ночи, а пламя смягчается, превращаясь в элегантное, текучее голубое сияние, словно тихая река света, окутывающая его фигуру. Клюв и когти, оформленные в строгих линиях, блестят, как отполированный темный металл, подчеркивая хищную грацию и незыблемость мифической силы."]}),"\n"]})]})}),(0,s.jsx)(r,{title:"Навыки и умения",children:(0,s.jsxs)(h,{children:[(0,s.jsx)(d,{title:"Эрудиция",children:(0,s.jsx)(l.p,{children:"Являясь Великим Архивариусом с большим послужным списком, персонаж владеет глубокими знаниями о мире вплоть до EX-ранга доступа. Благодаря работе Тройственного Узла, собирающего информацию у молодых грешников, владеет обширной информацией и о верхнем мире."})}),(0,s.jsx)(d,{title:"Артефакторика и алхимия",children:(0,s.jsx)(l.p,{children:"Салазар преуспевает в поиске ингредиентов, анализе материалов, изготовлении магических приспособлений и составов. Способен ремонтировать и настраивать даже сложнейшие механизмы."})}),(0,s.jsx)(d,{title:"Квелларий",children:(0,s.jsx)(l.p,{children:"Исследуя библиотеки Да’ат и Тиферет, феникс получил опыт работы с большим пластом материалов на языках прошлого. Он может расшифровывать записи на древней письменности и составлять печати не только на среднем, но и древнем квелларии."})}),(0,s.jsx)(d,{title:"Владение пером",children:(0,s.jsx)(l.p,{children:"Персонаж способен выполнять сложные чертежи, строить диаграммы и просто рисовать для души. Его почерк безупречен. Годы опыта составления магических печатей научили, что малейшее подрагивание пера может привести к катастрофе."})}),(0,s.jsx)(d,{title:"Ораторское и актерское мастерство",children:(0,s.jsx)(l.p,{children:"С самого основания ЦТУ Салазар исполняет в организации роль лидера, облик и характер которого сменяется каждые десять лет. Персонаж преуспевает в импровизации, создании образов и убеждении других членов общества силой слова."})}),(0,s.jsx)(d,{title:"Физическое развитие и самооборона",children:(0,s.jsx)(l.p,{children:"Хорошее физическое развитие, знание техник самообороны. Наемные мастера боевых искусств до сих пор поддерживают физическую форму персонажа."})}),(0,s.jsx)(d,{title:"Танец",children:(0,s.jsx)(l.p,{children:"Культура фэнхуан прочно базируется на эстетике ритуального танца. В Энкраже Салазар увлекся этим искусством и к настоящему времени, благодаря многочисленным преподавателям, он знаком с большинством самых известных движений. Феникс гибок, подвижен и артистичен. Он может элегантно вальсировать с партнером в цикл Луны и кружить в водовороте безудержного танго в цикл Солнца. Пламя и танец идут рука об руку, разделяя один мотив и одну суть."})}),(0,s.jsx)(d,{title:"Магия огня",children:(0,s.jsx)(l.p,{children:"Как фэнхуан, Салазар владеет магией огня, способен создавать пламя, управлять им и использовать для атаки, защиты и создания иллюзий."})}),(0,s.jsx)(d,{title:"Маскировка и иллюзии",children:(0,s.jsx)(l.p,{children:"Салазар развил способность менять черты лица и объем тела, а также создавать сложные иллюзии, что делает его мастером маскировки."})})]})}),(0,s.jsx)(r,{title:"Слабости",children:(0,s.jsxs)(h,{children:[(0,s.jsx)(d,{title:"Маска фэнхуан",children:(0,s.jsx)(l.p,{children:"Маска фэнхуан при повреждении может нанести непоправимый ущерб персонажу. Смены циклов приносят сложности в адаптации. Феникс бережно относится к симметрии среди своих сородичей. Он будет стараться предотвратить гибель другого фэнхуана любой ценой."})}),(0,s.jsx)(d,{title:"Ментальная нестабильность",children:(0,s.jsx)(l.p,{children:"Тщательно скрываемое и проявляемое лишь в малейших движениях и оброненных словах безумие персонажа может раскрыться в критической обстановке, спутывая и без того разрозненные карты."})}),(0,s.jsx)(d,{title:"Привязанность к подчиненным и друзьям",children:(0,s.jsx)(l.p,{children:"Угроза тем, кого феникс считает близкими, может заставить его действовать поспешно и иррационально."})}),(0,s.jsx)(d,{title:"Дерзость и отрицание авторитета",children:(0,s.jsx)(l.p,{children:"Дерзость, насмешки, отрицание авторитета феникса. Все это может заставить Салазара выйти из себя. В противовес, хорошая еда, вино, соблюдение этикета и дорогие подарки способны расположить Фейнмана к грешнику."})}),(0,s.jsx)(d,{title:"Роль поддержки",children:(0,s.jsx)(l.p,{children:"В боевом плане Салазар не обладает оружием и выполняет роль поддержки. По сути у него лишь одна боевая способность, тогда как остальные нацелены на помощь другим грешникам. Оставшись один на один с противником, Архивариус предпочтет покинуть поле боя, нежели сражаться."})}),(0,s.jsx)(d,{title:"Уязвимость к Воде",children:(0,s.jsx)(l.p,{children:"Контакт с аспектом Воды приносит наибольшее неудобство огненному фениксу. Ему неприятны дождь, снег, а резкое погружение в воду мира дезориентирует его. Истинная форма фэнхуана в Море Кровавых Слез будет представлять жалкое зрелище."})}),(0,s.jsx)(d,{title:"Пресса",children:(0,s.jsx)(l.p,{children:"Салазар всей душой презирает журналистику как явление. Даже спустя века разрешения репутационных скандалов, он предпочитает сваливать их решение на откуп подчиненных, а интервью дает с огромной неохотой. Интересно, что писать научные статьи в Эфемерид ему все же нравится."})}),(0,s.jsx)(d,{title:"Ментальная уязвимость",children:(0,s.jsx)(l.p,{children:"Несмотря на наличие у себя возможности влиять на разум грешников, способностей для защиты от таких воздействий не имеет. При этом вступая в зрительный контакт с существами и персонажами он уменьшает свою ментальную защиту. Иными словами, сиддарт — его главный враг."})}),(0,s.jsx)(d,{title:"Связь с Похотью",children:(0,s.jsx)(l.p,{children:"Несмотря на то, что грех Похоти является частью сути Салазара, он также представляет собой ключ к его уязвимости. Эксплуатируя как связь персонажа с Теневым Пауком, так и близкие контакты разного рода, можно узнать намного больше, чем при обычном общении."})})]})}),(0,s.jsx)(r,{title:"Связанные персонажи",children:(0,s.jsxs)(h,{children:[(0,s.jsx)(d,{title:"Эмма Кальдер",children:(0,s.jsx)(l.p,{children:"27 лет. Молодая ученая, в рамках хобби собирающая исторические свидетельства о культе, организованном Салазаром при жизни. Эмма — интроверт с аналитическим умом и острым чувством несправедливости. Девушку нередко одолевает желание иметь ту же признанность, что и её более успешные коллеги. Временами она может незаметно манипулировать фактами, чтобы выставить себя в более выгодном свете. Подвержена греху Зависти. Предмет связи — сережка с рубином."})}),(0,s.jsx)(d,{title:"Виктор Реннер",children:(0,s.jsx)(l.p,{children:"45 лет. Возглавляет крупный инвестиционный фонд, известный агрессивными методами ведения бизнеса. Часто выступает на финансовых конференциях и продвигает идею «успеха любой ценой». Виктор — прирождённый стратег, для которого деньги — не только цель, но и инструмент власти. Он безразличен к чужим чувствам, хотя умеет создавать иллюзию участия и заботы. Его амбиции не знают предела, он готов идти на жертвы ради сохранения и приумножения своего капитала. Подвержен греху Алчности. Предмет связи — платиновое кольцо."})}),(0,s.jsx)(d,{title:"Майлз Арчер",children:(0,s.jsx)(l.p,{children:"31 год. Настоятель одного из крупнейших храмов саентологии в мегаполисе, организует семинары по самопознанию и духовному росту. Майлз стремится к лидерству и жаждет одобрения со стороны высшего руководства церкви. Он искренне верит, что достиг духовного просветления, но его высокомерие мешает ему увидеть собственные пороки. Он может быть жёстким с прихожанами, не терпит сомнений в своей правоте. Подвержен греху Гордыни. Предмет связи — восьмиконечный крест."})})]})})]}),(0,s.jsx)(x,{children:(0,s.jsx)(l.p,{children:"Не бог создал человека по своему образу и подобию, а человек всегда творил бога по своему образцу, наделяя его своим умом, своими качествами, особенно — пороками"})})]})}function i(n,s){throw Error("Expected "+(s?"component":"object")+" `"+n+"` to be defined: you likely forgot to import, pass, or provide it.")}n.s(["default",0,function(n={}){let{wrapper:i}={...(0,e.useMDXComponents)(),...n.components};return i?(0,s.jsx)(i,{...n,children:(0,s.jsx)(l,{...n})}):l(n)}])}]);